"""Generate the supplementary tables (LaTeX tabular bodies) from saved outputs. Generated files; do not edit.
Inputs : sample/raw/funnel.json, analysis/outputs/{stats.json, figS2.csv, figS3.csv, models_table.csv},
         figures/tables/tableS5_per_vendor.tex
Outputs: paper/tables/supp_buckets.tex, supp_exclusions.tex, supp_failures.tex, supp_per_cmp.tex, supp_models.tex, supp_vendor.tex
"""
import json
import os

import pandas as pd

HERE = os.path.dirname(os.path.abspath(__file__))
STUDY = os.path.dirname(os.path.dirname(HERE))
OUT = os.path.join(STUDY, 'analysis', 'outputs')


def n(x):
    return f'{int(x):,}'.replace(',', '{,}')


def w(path, lines):
    open(os.path.join(HERE, path), 'w').write('% GENERATED by supp_tables.py; do not edit by hand.\n' + '\n'.join(lines) + '\n')


funnel = json.load(open(os.path.join(STUDY, 'sample', 'raw', 'funnel.json')))
s3 = pd.read_csv(os.path.join(OUT, 'figS3.csv'))
cap = s3[s3.metric == 'banner'].set_index('bucket')['n']
lines = []
for b, v in funnel['per_bucket'].items():
    label = b.replace('-', '--')
    lines.append(f"{label} & {n(v['tranco_domains'])} & {n(v['resolved'])} & {n(v['flagged_N'])} & {n(v['drawn_n'])} & "
                 f"{n(v['verified_live_online_store'])} & {n(v['sample'])} & {n(cap.get(b, 0))} & {v['weight']:.2f} \\\\")
tot = funnel
lines.append('\\midrule')
lines.append(f"Total & {n(tot['top_n'])} & {n(tot['domains_with_any_A_record'])} & {n(tot['dns_flagged_shopify'])} & {n(tot['drawn_for_verification'])} & "
             f"{n(tot['verified_live_online_store'])} & {n(tot['sample_after_dedupe'])} & {n(cap.sum())} & \\\\")
w('supp_buckets.tex', lines)

LAB = {'headless_or_assets_only': 'Headless storefront or Shopify assets only', 'no_product_url': 'No product-page URL',
       'blocked_http_403': 'Blocked (HTTP 403)', 'child_directed': 'Aimed at children', 'duplicate_of': 'Duplicate of the same shop',
       'adult_content': 'Adult content', 'fetch_error': 'Fetch error (connection or TLS)', 'no_shopify_markers': 'No Shopify storefront markers',
       'password_protected': 'Password-protected', 'http_402': 'HTTP 402 (store unavailable)', 'http_404': 'HTTP 404',
       'http_409': 'HTTP 409', 'http_423': 'HTTP 423', 'http_500': 'HTTP 500'}
ex = funnel['exclusion_reasons']
lines = [f"{LAB.get(k, k)} & {n(v)} \\\\" for k, v in ex.items()]
lines += ['\\midrule', f"Total excluded of {n(funnel['drawn_for_verification'])} verified & {n(sum(ex.values()))} \\\\"]
w('supp_exclusions.tex', lines)

S = json.load(open(os.path.join(OUT, 'stats.json')))
FL = {'redirect_off_site': 'Redirected to another site (google.com)', 'http_404_product_gone': 'Product page gone (HTTP 404)',
      'no_window_Shopify': 'No Shopify page object', 'dns_not_resolved': 'DNS failure', 'http_403': 'HTTP 403',
      'http_402_store_unavailable': 'HTTP 402 (store unavailable)'}
fb = S['context']['failed_by_reason']
lines = [f"{FL.get(k, k)} & {n(v)} \\\\" for k, v in fb.items()]
lines += ['\\midrule', f"Total unusable loads (of {n(S['design']['n_loads_total'])}) & {n(sum(fb.values()))} \\\\"]
w('supp_failures.tex', lines)

s2 = pd.read_csv(os.path.join(OUT, 'figS2.csv'))
NAMES = {'pandectes': 'Pandectes', 'onetrust': 'OneTrust', 'shopify_native': "Shopify's banner", 'cookiebot': 'Cookiebot',
         'osano': 'Osano', 'iubenda': 'iubenda', 'usercentrics': 'Usercentrics', 'axeptio': 'Axeptio', 'trustarc': 'TrustArc',
         'ketch': 'Ketch', 'clarip': 'Clarip', 'cookiescript': 'CookieScript', 'cookieyes': 'CookieYes', 'other': 'Other or none'}
MET = ['region_denied', 'prechoice_sbx', 'reject_first_layer', 'reached', 'after_decline', 'gpc_resid']
lines = []
for cmp_, g in s2.groupby('cmp', sort=False):
    g = g.set_index('metric')
    cells = []
    for m in MET:
        if m in g.index and g.loc[m, 'n'] > 0:
            r = g.loc[m]
            cells.append(f"{int(r.k)}/{int(r.n)} ({100 * r.p:.0f})" if r.n >= 5 else f"{int(r.k)}/{int(r.n)}")
        else:
            cells.append('--')
    mode = g['mode'].iloc[0] if isinstance(g['mode'].iloc[0], str) else '--'
    lines.append(f"{NAMES.get(cmp_, cmp_)} & {mode} & {int(g['n_banner'].iloc[0])} & " + ' & '.join(cells) + ' \\\\')
w('supp_per_cmp.tex', lines)

# Models (analysis/outputs/models_table.csv): Firth models with profile-penalised-likelihood CIs and
# mixed models with a random intercept per consent product (Wald CIs).
mt = pd.read_csv(os.path.join(OUT, 'models_table.csv'))
TERM = {'mgroup=Blocker only / unknown / none': 'Blocker only, unknown or none (vs Shopify banner)',
        'mgroup=CMP writes to Shopify API': 'CMP writes to Shopify (vs Shopify banner)',
        'refused': 'Shopify recorded an explicit refusal',
        'region_optout': "Region default `allowed until choice'"}
lines, last = [], None
for _, r in mt.iterrows():
    if r.model != last:
        if last is not None:
            lines.append('\\addlinespace')
        meth = 'Firth' if str(r.method).startswith('Firth') else 'random intercept per product'
        lines.append(f"\\multicolumn{{4}}{{@{{}}l}}{{\\emph{{{r.model}}} ({meth}; events {int(r.events)} of {int(r.n)} stores)}} \\\\")
        last = r.model
    ev = f"{int(r.events_term)}/{int(r.n_term)}" if pd.notna(r.n_term) else '--'
    lines.append(f"\\quad {TERM.get(r.term, r.term)} & {ev} & {r.OR:.2f} & {r.lo:.2f}--{r.hi:.2f} \\\\")
w('supp_models.tex', lines)

# Per-vendor table (Supplementary Table S5): rows of figures/tables/tableS5_per_vendor.tex, generated by the figure stage
src = open(os.path.join(STUDY, 'figures', 'tables', 'tableS5_per_vendor.tex')).read()
body = src.split('\\midrule', 1)[1].split('\\bottomrule', 1)[0].strip().splitlines()
w('supp_vendor.tex', [l.replace(' of ', ' of~') for l in body if l.strip()])
# Sensitivity to the stores flagged in the ethics review (Supplementary Table S7; review COORD-01, AUD-04):
# analysis/outputs/stats.json 'ethics_sensitivity', computed by analysis/analyze.py
E = S['ethics_sensitivity']
ROWS = [('prechoice', 'Pre-choice, all stores'), ('banner_fires', 'Pre-choice, banner stores'),
        ('nobanner_fires', 'Pre-choice, no-banner stores'),
        ('optout_fires', "Pre-choice, default `allowed'"), ('optin_fires', "Pre-choice, default `denied'"),
        ('blocklist', 'Blocklist: declared vendor fired'), ('decline_fresh', 'Decline: new sandbox, next page'),
        ('gpc', 'GPC: still fired'),
        ('gate_informative', 'Gate: denied purpose at start'), ('gate_gpc_sale', 'Gate: sale pixels started (GPC)'),
        ('gate_default_denied_held', 'Gate: marketing pixels held'),
        ('creator_reached', 'Creator: code reached a vendor'), ('creator_reached_nongoogle', 'Creator: non-Google vendor'),
        ('creator_reached_sandboxed', 'Creator: sent from a sandbox')]
lines = []
for k, lab in ROWS:
    cells = []
    for v in ('all', 'excl_flagged'):   # content-flagged stores are excluded from the whole analysis since 2026-09-29
        r = E['variants'][v][k]
        cells.append(f"{n(r['k'])}/{n(r['n'])} ({100 * r['p']:.1f})")
    lines.append(f"{lab} & " + ' & '.join(cells) + ' \\\\')
    if k in ('gpc', 'gate_default_denied_held'):
        lines.append('\\addlinespace')
w('supp_ethics.tex', lines)
json.dump(dict(n_flagged=E['n_flagged'], n_excluded={v: E['variants'][v]['n_excluded'] for v in E['variants']},
               max_abs_change_pp_flagged=round(E['max_abs_change_pp_flagged'], 1)), open(os.path.join(HERE, 'supp_ethics.json'), 'w'), indent=1)
print('ok')
